from datetime import datetime

def valid_date(date):
    if not date:
        return False
    try:
        datetime.strptime(date, '%m-%d-%Y')
        day, month, year = map(int, date.split('-'))
        if month in [1, 3, 5, 7, 8, 10, 12]:
            if not 1 <= day <= 31:
                return False
        elif month in [4, 6, 9, 11]:
            if not 1 <= day <= 30:
                return False
        elif month == 2:
            if not 1 <= day <= 29:
                return False
        if not 1 <= month <= 12:
            return False
        return True
    except ValueError:
        return False
